-- GENERATED by `npm run menu:sql` from the rehearsal-grill tenant config. Do not edit by hand.
-- Apply to the tenant's database BEFORE deploying a menu or price change: until
-- it is applied, create_order refuses the new prices.
do $menu$
begin
with upserted as (
  insert into public.menu_items (name, category, price, available_until)
  values
    ('Fictional rehearsal dish', 'Fictional rehearsal category', 100.00, null),
    ('Fictional rehearsal soft drink', 'Non-alcoholic drinks', 25.00, null)
  on conflict (name) do update set
    category = excluded.category,
    price = excluded.price,
    available_until = excluded.available_until,
    available = true,
    updated_at = now()
  returning name
)
update public.menu_items
set available = false, updated_at = now()
where available and name not in (select name from upserted);

  if exists (select from information_schema.columns where table_schema = 'public' and table_name = 'menu_items' and column_name = 'extras') then
    update public.menu_items set extras = '[]'::jsonb where extras <> '[]'::jsonb;
  end if;
end $menu$;
